type Cache struct {
	mu sync.RWMutex
	m  map[string]int
}

func (c *Cache) Get(k string) (int, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	v, ok := c.m[k]
	return v, ok
}

func (c *Cache) Set(k string, v int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.m[k] = v
}

var config = sync.OnceValue(func() map[string]string {
	fmt.Println("carregando...") // roda uma única vez
	return map[string]string{"env": "prod"}
})

func main() {
	var hits atomic.Int64
	var wg sync.WaitGroup
	c := &Cache{m: map[string]int{}}
	for i := range 50 {
		wg.Go(func() {
			c.Set("k", i)
			hits.Add(1)
			_ = config()["env"]
		})
	}
	wg.Wait()
	_, ok := c.Get("k")
	fmt.Println(hits.Load(), ok, config()["env"])
}

