type Result struct {
	ID, Square int
}

func worker(jobs <-chan int, out chan<- Result) {
	for n := range jobs { // termina quando jobs é fechado e esvaziado
		out <- Result{n, n * n}
	}
}

func main() {
	jobs := make(chan int)
	out := make(chan Result)

	var wg sync.WaitGroup
	for range 4 {
		wg.Go(func() { worker(jobs, out) })
	}

	go func() { // produtor: quem envia é quem fecha
		defer close(jobs)
		for i := 1; i <= 8; i++ {
			jobs <- i
		}
	}()

	go func() { // fecha out quando todos os workers saírem
		wg.Wait()
		close(out)
	}()

	total := 0
	for r := range out {
		total += r.Square
	}
	fmt.Println(total) // 204
}

