	"sync/atomic"
	"time"
)

func main() {
	sem := make(chan struct{}, 3) // no máximo 3 simultâneas
	var wg sync.WaitGroup
	var cur, peak atomic.Int32

	for range 10 {
		sem <- struct{}{} // bloqueia quando há 3 em voo
		wg.Go(func() {
			defer func() { <-sem }()
			n := cur.Add(1)
			for {
				p := peak.Load()
				if n <= p || peak.CompareAndSwap(p, n) {
					break
				}
			}
			time.Sleep(10 * time.Millisecond) // trabalho
			cur.Add(-1)
		})
	}
	wg.Wait()
	fmt.Println("pico:", peak.Load()) // 3
}

