import (
	"context"
	"fmt"
	"net/http"

	"golang.org/x/sync/errgroup"
	"golang.org/x/time/rate"
)

func fetchAll(ctx context.Context, urls []string) error {
	g, ctx := errgroup.WithContext(ctx)
	g.SetLimit(8) // no máximo 8 goroutines ativas; g.Go bloqueia se cheio
	lim := rate.NewLimiter(rate.Limit(20), 5) // 20 req/s, rajada de 5

	for _, u := range urls {
		g.Go(func() error {
			if err := lim.Wait(ctx); err != nil { // respeita cancelamento
				return err
			}
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
			if err != nil {
				return err
			}
			resp, err := http.DefaultClient.Do(req)
			if err != nil {
				return err
			}
			return resp.Body.Close()
		})
	}
	return g.Wait() // primeiro erro não-nil; o ctx já foi cancelado
}

func main() { fmt.Println(fetchAll(context.Background(), nil)) }

