package main

import (
	"context"
	"fmt"
	"runtime"
	"time"
)

// VAZA: sem buffer, se o chamador desistir o envio bloqueia para sempre.
func buscaVaza(d time.Duration) string {
	ch := make(chan string) // sem buffer
	go func() {
		time.Sleep(20 * time.Millisecond)
		ch <- "resultado"
	}()
	select {
	case r := <-ch:
		return r
	case <-time.After(d):
		return "timeout"
	}
}

// OK: buffer 1 garante que o envio nunca bloqueia.
func buscaOK(ctx context.Context) string {
	ch := make(chan string, 1)
	go func() {
		time.Sleep(20 * time.Millisecond)
		ch <- "resultado"
	}()
	select {
	case r := <-ch:
		return r
	case <-ctx.Done():
		return ctx.Err().Error()
	}
}

func main() {
	for range 100 {
		buscaVaza(time.Millisecond)
	}
	time.Sleep(100 * time.Millisecond)
	fmt.Println("vazadas:", runtime.NumGoroutine()-1)

	for range 100 {
		ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond)
		buscaOK(ctx)
		cancel()
	}
	time.Sleep(100 * time.Millisecond)
	fmt.Println("vazadas:", runtime.NumGoroutine()-1)
}

